="width:<?=$w?>%"></div></div><strong><?=bi_step22_money($r['sales_revenue'])?></strong></div><?php endforeach;?></div></article><article class="os-card bi-span-6"><h2>New Leads</h2><div class="bi-bars"><?php foreach($rows as $r):$w=min(100,(float)$r['new_leads']/$maxLeads*100);?><div class="bi-bar-row"><span><?=bi_step22_h($r['label'])?></span><div class="bi-bar-track"><div class="bi-bar-fill" style="width:<?=$w?>%"></div></div><strong><?=$r['new_leads']?></strong></div><?php endforeach;?></div></article><article class="os-card bi-span-12"><div class="os-title-row"><div><h2>Cross-Module Monthly Matrix</h2><p>Verified Profit excludes sales with incomplete cost basis.</p></div></div><div class="bi-table-wrap"><table class="bi-table"><thead><tr><th>Month</th><th>Sales</th><th>Revenue</th><th>VP</th><th>Verified Profit</th><th>Deferred Cost Sales</th><th>Collections</th><th>Purchases</th><th>New Leads</th><th>Conversions</th><th>Finance Income</th><th>Finance Expense</th><th>Finance Net</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=bi_step22_h($r['label'])?></td><td><?=$r['sales_count']?></td><td><?=bi_step22_money($r['sales_revenue'])?></td><td><?=bi_step22_num($r['sales_vp'],3)?></td><td><?=bi_step22_money($r['verified_profit'])?></td><td><?=$r['profit_deferred_sales']?></td><td><?=bi_step22_money($r['collections'])?></td><td><?=bi_step22_money($r['purchase_spend'])?></td><td><?=$r['new_leads']?></td><td><?=$r['lead_conversions']?></td><td><?=bi_step22_money($r['finance_income'])?></td><td><?=bi_step22_money($r['finance_expense'])?></td><td><?=bi_step22_money($r['finance_net'])?></td></tr><?php endforeach;?></tbody></table></div></article></section><?php endif;?></main></body></html>